+  <script>
+    const toggle = document.getElementById('theme-toggle');
+    const root = document.documentElement;
+    const savedTheme = localStorage.getItem('upb-theme');
+    if (savedTheme === 'night' || savedTheme === 'day') root.setAttribute('data-theme', savedTheme);
+    function updateToggle() {
+      const night = root.getAttribute('data-theme') === 'night';
+      toggle.setAttribute('aria-pressed', String(night));
+      toggle.setAttribute('aria-label', night ? 'Switch to day mode' : 'Switch to night mode');
+      toggle.innerHTML = night ? '<span aria-hidden="true">☀</span><span>Day mode</span>' : '<span aria-hidden="true">☾</span><span>Night mode</span>';
+    }
+    updateToggle();
+    toggle.addEventListener('click', () => {
+      const nextTheme = root.getAttribute('data-theme') === 'night' ? 'day' : 'night';
+      root.setAttribute('data-theme', nextTheme);
+      localStorage.setItem('upb-theme', nextTheme);
+      updateToggle();
+    });
+  </script>
+</body>
+</html>

